import type { DatafnExecutor } from "@datafn/server";
import {
  AdminError,
  decodeAdminCursor,
  encodeAdminCursor,
  normalizeAdminPageLimit,
  type AdminOperationContext,
  type AdminOperationResult,
} from "@superfunctions/admin";
import type {
  DataFnAdminService,
  DataFnAdminServiceRequest,
} from "./index.js";

type JsonRecord = Record<string, unknown>;

export interface DataFnDomainAdminServiceOptions<TContext> {
  executor: DatafnExecutor<TContext>;
  /** Builds the exact DataFn context used by authorization and namespace providers. */
  context(admin: AdminOperationContext): TContext;
}

function object(value: unknown, name: string): JsonRecord {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new AdminError("invalid_argument", `${name} must be an object.`);
  }
  return value as JsonRecord;
}

function string(value: unknown, name: string): string {
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new AdminError("invalid_argument", `${name} must be a non-empty string.`);
  }
  return value;
}

function resultItem(value: object): AdminOperationResult<JsonRecord> {
  return { ok: true, data: { item: { ...value } } };
}

function page(
  values: object[],
  input: JsonRecord,
  context: AdminOperationContext,
): AdminOperationResult<JsonRecord> {
  const limit = normalizeAdminPageLimit(input.limit);
  const offset = typeof input.cursor === "string"
    ? decodeAdminCursor<{ offset: number }>(input.cursor, context.scope).offset
    : 0;
  if (!Number.isInteger(offset) || offset < 0) {
    throw new AdminError("invalid_argument", "The DataFn admin cursor is invalid.");
  }
  const items = values.slice(offset, offset + limit).map((entry) => ({ ...entry }));
  const next = offset + items.length;
  const nextCursor = next < values.length
    ? encodeAdminCursor(context.scope, { offset: next })
    : null;
  return {
    ok: true,
    data: { items, nextCursor },
    page: { nextCursor, hasMore: next < values.length },
  };
}

function resourceId(value: { name: string }): string {
  return value.name;
}

function relationId(value: { from: string | string[]; to: string | string[]; type: string }): string {
  return `${[].concat(value.from as never).join(",")}->${[].concat(value.to as never).join(",")}:${value.type}`;
}

function schemaDocuments<TContext>(executor: DatafnExecutor<TContext>) {
  return {
    schemas: [{
      id: `schema-v${executor.schema.version ?? 1}`,
      version: executor.schema.version ?? 1,
      namespaced: executor.schema.namespaced !== false,
      resourceCount: executor.schema.resources.length,
      relationCount: executor.schema.relations?.length ?? 0,
    }],
    resources: executor.schema.resources.map((resource) => ({ ...resource, id: resourceId(resource) })),
    relations: (executor.schema.relations ?? []).map((relation) => ({ ...relation, id: relationId(relation) })),
    indices: executor.schema.resources.map((resource) => ({
      id: resource.name,
      resource: resource.name,
      indices: resource.indices ?? [],
    })),
    capabilities: executor.schema.resources.map((resource) => ({
      id: resource.name,
      resource: resource.name,
      capabilities: resource.capabilities ?? [],
      schemaCapabilities: executor.schema.capabilities ?? [],
    })),
  };
}

function findById(values: Array<{ id: string }>, id: string, label: string): object {
  const value = values.find((entry) => entry.id === id);
  if (!value) throw new AdminError("not_found", `${label} was not found in the active DataFn schema.`);
  return value;
}

function splitRecordId(value: string): { resource: string; id: string } {
  const separator = value.indexOf(":");
  if (separator <= 0 || separator === value.length - 1) {
    throw new AdminError("invalid_argument", "DataFn record IDs use the form resource:id.");
  }
  return { resource: value.slice(0, separator), id: value.slice(separator + 1) };
}

/** Uses DataFn's transport-neutral executor so admin calls retain namespace, policy, hooks, limits, and rate limiting. */
export function createDataFnDomainAdminService<TContext>(
  options: DataFnDomainAdminServiceOptions<TContext>,
): DataFnAdminService {
  const { executor } = options;
  return {
    async execute(request: DataFnAdminServiceRequest) {
      const input = object(request.input ?? {}, "input");
      const documents = schemaDocuments(executor);
      const domainContext = options.context(request.context);
      const [module, resource, action] = request.operationId.split(".");
      if (module !== "datafn") throw new AdminError("not_found", "Unknown DataFn operation.");

      if (action === "list" && resource && resource in documents && resource !== "records") {
        return page(documents[resource as keyof typeof documents], input, request.context);
      }
      if (action === "get" && resource && resource in documents && resource !== "records") {
        return resultItem(findById(
          documents[resource as keyof typeof documents] as Array<{ id: string }>,
          string(input.id, "id"),
          resource,
        ));
      }
      if (request.operationId === "datafn.records.list") {
        const filter = object(input.filter, "filter");
        const target = string(filter.resource, "filter.resource");
        const definition = executor.schema.resources.find((entry) => entry.name === target);
        if (!definition) throw new AdminError("not_found", "DataFn resource was not found in the active schema.");
        const query = {
          ...filter,
          resource: target,
          version: String(filter.version ?? definition.version),
          limit: input.limit,
        };
        delete query.cursor;
        const domain = await executor.query<JsonRecord>(query, domainContext);
        const values = Array.isArray(domain.data) ? domain.data : [];
        return {
          ok: true,
          data: { items: values, nextCursor: domain.nextCursor ?? null },
          page: {
            nextCursor: typeof domain.nextCursor === "string" ? domain.nextCursor : null,
            hasMore: typeof domain.nextCursor === "string",
          },
        };
      }
      if (request.operationId === "datafn.records.get") {
        const target = splitRecordId(string(input.id, "id"));
        const definition = executor.schema.resources.find((entry) => entry.name === target.resource);
        if (!definition) throw new AdminError("not_found", "DataFn resource was not found in the active schema.");
        const domain = await executor.query<JsonRecord>({
          resource: target.resource,
          version: String(definition.version),
          filters: { id: target.id },
          limit: 1,
        }, domainContext);
        const value = Array.isArray(domain.data) ? domain.data[0] : undefined;
        if (!value || typeof value !== "object") throw new AdminError("not_found", "DataFn record was not found.");
        return resultItem({ ...value, id: `${target.resource}:${target.id}` });
      }
      if (request.operationId === "datafn.queries.query") {
        return { ok: true, data: { accepted: true, item: await executor.query(object(input.payload, "payload"), domainContext) } };
      }
      if (request.operationId === "datafn.records.mutate") {
        return { ok: true, data: { accepted: true, item: await executor.mutate(object(input.payload, "payload"), domainContext) } };
      }
      if (request.operationId === "datafn.records.transact") {
        return { ok: true, data: { accepted: true, item: await executor.transact(object(input.payload, "payload"), domainContext) } };
      }
      throw new AdminError("not_found", `Unsupported DataFn admin operation: ${request.operationId}.`);
    },
  };
}

