    expect(result.data).toEqual({
      operationId: "filefn.files.list",
      namespace: "tenant_1",
      region: "in-south",
    });
    expect(execute).toHaveBeenCalledWith({
      operationId: "filefn.files.list",
      input: { limit: 25 },
      context,
    });
  });
});
